<?php
require __DIR__.'/includes/bootstrap.php';require_auth();require __DIR__.'/includes/layout.php';require __DIR__.'/includes/data.php';
$action=$_GET['action']??'';$id=(int)($_GET['id']??0);if($_SERVER['REQUEST_METHOD']==='POST'||in_array($action,['create','edit','delete'],true))require_permission('catalog.manage');
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$name=trim((string)($_POST['name']??''));$unit=(int)($_POST['unit_id']??0);$status=($_POST['status']??'active')==='inactive'?'inactive':'active';$description=trim((string)($_POST['description']??''));
    if($name===''||!$unit){flash('error','Raw item name and unit are required.');redirect('products.php?action='.($id?'edit&id='.$id:'create'));}
    if($id){$q=$pdo->prepare('UPDATE products SET unit_id=?,name=?,description=?,status=? WHERE id=?');$q->execute([$unit,$name,$description,$status,$id]);audit($pdo,'update','raw_items',$id,null,['name'=>$name,'unit_id'=>$unit]);flash('success',$name.' updated.');}
    else{do{$sku='RAW-'.strtoupper(substr(bin2hex(random_bytes(5)),0,8));$q=$pdo->prepare('SELECT COUNT(*) FROM products WHERE sku=?');$q->execute([$sku]);}while((int)$q->fetchColumn());$q=$pdo->prepare('INSERT INTO products(unit_id,sku,name,description,cost_price,selling_price,minimum_stock,status) VALUES(?,?,?, ?,0,0,0,?)');$q->execute([$unit,$sku,$name,$description,$status]);$id=(int)$pdo->lastInsertId();audit($pdo,'create','raw_items',$id,null,['name'=>$name,'unit_id'=>$unit]);flash('success',$name.' added. You can now receive stock for this item.');}
    redirect('products.php');
}
if($action==='delete'&&$id){$pdo->prepare('UPDATE products SET deleted_at=NOW() WHERE id=?')->execute([$id]);audit($pdo,'archive','raw_items',$id);flash('success','Raw item archived.');redirect('products.php');}
$item=[];if($id){$q=$pdo->prepare('SELECT * FROM products WHERE id=?');$q->execute([$id]);$item=$q->fetch()?:[];}$form=in_array($action,['create','edit']);
render_header('Raw Items','products');page_title('Raw Items','ITEM MASTER','First add the raw items you purchase—only a name and counting unit are required.',$form?'':'Add Raw Item',app_url('products.php?action=create'));
if($form):$units=options($pdo,'units','CONCAT(name," (",symbol,")")','status="active"');?>
<article class="card form-card raw-item-form"><div class="card-head"><div><h2><?=$id?'Edit raw item':'New raw item'?></h2><small>No barcode, category, selling price or payment method.</small></div><span class="status">SIMPLE ITEM</span></div><form method="post"><?=csrf_field()?><div class="form-grid"><label>Raw Item Name *<input name="name" required autofocus placeholder="Example: Beef, Cauliflower, Flour" value="<?=e($item['name']??'')?>"></label><label>Counting Unit *<select name="unit_id" required><option value="">Choose kg, piece, litre…</option><?php foreach($units as $x):?><option value="<?=$x['id']?>"<?=selected($item['unit_id']??'',$x['id'])?>><?=e($x['label'])?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="active">Active</option><option value="inactive"<?=selected($item['status']??'','inactive')?>>Inactive</option></select></label><label class="full">Note (optional)<textarea name="description" placeholder="Storage or handling note"><?=e($item['description']??'')?></textarea></label></div><div class="form-actions"><a class="btn" href="<?=app_url('products.php')?>">Cancel</a><button class="btn primary">Save Raw Item</button></div></form></article>
<?php else:$rows=$pdo->query('SELECT p.id,p.name,p.description,p.status,u.symbol,COALESCE(SUM(it.quantity_in-it.quantity_out),0) available,COALESCE(SUM(CASE WHEN it.transaction_type="receiving" THEN it.quantity_in ELSE 0 END),0) received FROM products p JOIN units u ON u.id=p.unit_id LEFT JOIN inventory_transactions it ON it.product_id=p.id WHERE p.deleted_at IS NULL GROUP BY p.id,p.name,p.description,p.status,u.symbol ORDER BY p.name')->fetchAll();?>
<div class="raw-item-actions"><a class="dashboard-action primary-action" href="<?=app_url('products.php?action=create')?>"><span><i data-icon="plus"></i></span><div><b>Add Raw Item</b><small>Create the item name and unit first</small></div><em>→</em></a><a class="dashboard-action" href="<?=app_url('receiving.php?action=create')?>"><span><i data-icon="inbox"></i></span><div><b>Receive Stock</b><small>Add branch, brand, quantity and unit cost</small></div><em>→</em></a></div>
<article class="card table-card"><div class="table-toolbar"><div><b><?=count($rows)?> raw items</b><small style="display:block;color:var(--muted);margin-top:4px">Clean item list without unnecessary fields</small></div><input placeholder="Search raw items…" data-table-search></div><div class="table-wrap"><table><thead><tr><th>Raw Item</th><th>Unit</th><th>Total Received</th><th>Available</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td data-label="Raw Item"><b><?=e($row['name'])?></b><?php if($row['description']):?><small style="display:block;color:var(--muted)"><?=e($row['description'])?></small><?php endif;?></td><td data-label="Unit"><span class="unit-badge"><?=e($row['symbol'])?></span></td><td data-label="Total Received"><?=number_format($row['received'],3).' '.e($row['symbol'])?></td><td data-label="Available"><b><?=number_format($row['available'],3).' '.e($row['symbol'])?></b></td><td data-label="Status"><span class="status <?=$row['status']==='inactive'?'cancelled':''?>"><?=e(ucfirst($row['status']))?></span></td><td data-label="Action"><a class="btn small" href="?action=edit&id=<?=$row['id']?>">Edit</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6"><div class="empty"><div class="empty-icon"><i data-icon="package"></i></div>No raw items yet. Add your first item such as Beef or Cauliflower.</div></td></tr><?php endif;?></tbody></table></div></article><?php endif;render_footer('products');
